// The version of this C interface. It changes whenever a function signature, a struct layout
// or the meaning of a status code changes; a binding checks it at load time.
#define RTC_ABI_VERSION 1

// Success.
#define RTC_OK 0

// Success, nothing to return: a poll found its queue empty, a lookup found no value.
#define RTC_EMPTY 1

// An argument is null, out of range, not UTF-8, or names no such object.
#define RTC_ERR_INVALID_ARGUMENT -1

// The caller's buffer is too small; the size needed was written and the item kept.
#define RTC_ERR_BUFFER_TOO_SMALL -2

// The engine refused the call (W3C errors such as `InvalidStateError`, malformed SDP, ...).
#define RTC_ERR_ENGINE -3

// A JSON argument did not parse or did not match its schema.
#define RTC_ERR_JSON -4

// The call panicked inside the library; the handle is poisoned.
#define RTC_ERR_PANIC -5

// No object with this id (data channel, sender, receiver, transceiver).
#define RTC_ERR_NOT_FOUND -6

// A socket or thread operation failed (driven layer).
#define RTC_ERR_IO -7

// The handle is closed or poisoned.
#define RTC_ERR_CLOSED -8

// A message for the application: an RTP packet.
#define RTC_MESSAGE_RTP 1

// A message for the application: an RTCP compound packet.
#define RTC_MESSAGE_RTCP 2

// A message for the application: a data channel message.
#define RTC_MESSAGE_DATA 3

// The transport protocol of a datagram: UDP.
#define RTC_PROTOCOL_UDP 0

// The transport protocol of a datagram: TCP (framed by the application, RFC 4571).
#define RTC_PROTOCOL_TCP 1

// A peer connection of the sans-I/O layer (C: `rtc_pc`). Not thread-safe: calls on one handle
// must not overlap.
typedef struct rtc_pc rtc_pc;

// A socket address: `family` 4 or 6 (0: none), the address in network order (an IPv4 one in
// the first four bytes), the port in host order.
typedef struct rtc_addr {
  // 4 (IPv4), 6 (IPv6) or 0 (no address).
  uint8_t family;
  // The address bytes, network order; IPv4 uses the first four.
  uint8_t ip[16];
  // The port, host order.
  uint16_t port;
} rtc_addr;

// The 5-tuple of a datagram: where it arrived or leaves from (`local`), the other end
// (`peer`), [`RTC_PROTOCOL_UDP`] or [`RTC_PROTOCOL_TCP`], and its ECN codepoint (the two
// bits of the IP header: 0 Not-ECT, 1 ECT(1), 2 ECT(0), 3 CE).
typedef struct rtc_transport {
  // The local address.
  struct rtc_addr local;
  // The remote address.
  struct rtc_addr peer;
  // [`RTC_PROTOCOL_UDP`] or [`RTC_PROTOCOL_TCP`].
  uint8_t protocol;
  // The ECN codepoint (0 when not ECN-capable).
  uint8_t ecn;
} rtc_transport;

// A message for the application, from [`rtc_pc_poll_read`]: its kind
// ([`RTC_MESSAGE_RTP`], [`RTC_MESSAGE_RTCP`], [`RTC_MESSAGE_DATA`]), the receiver (RTP, RTCP)
// or data channel it is for, whether a data channel message is a string, when the packet
// arrived (the `now_ns` of its `handle_read`), and its length in the buffer.
typedef struct rtc_message {
  // The message kind.
  uint32_t kind;
  // 1 for a data channel string message, 0 otherwise.
  uint32_t is_string;
  // The receiver id (RTP, RTCP) or data channel id.
  uint64_t id;
  // When the packet carrying it arrived, in the caller's nanoseconds.
  uint64_t now_ns;
  // The length of the message in the caller's buffer.
  size_t len;
} rtc_message;

